import { createHash, randomUUID } from 'crypto';
import fs from 'fs/promises';
import path from 'path';
import {
  ProfileMediaSchema,
  type ProfileMedia as Media,
} from '../../types/design-profile';

export const PROFILE_IMAGE_BYTES = 20 * 1024 * 1024;
const extensions: Record<Media['mimeType'], string> = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'image/webp': '.webp',
  'image/gif': '.gif',
};

const imageType = (bytes: Buffer): Media['mimeType'] => {
  if (
    bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))
  )
    return 'image/png';
  if (bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255)
    return 'image/jpeg';
  if (/^GIF8[79]a$/.test(bytes.subarray(0, 6).toString('ascii')))
    return 'image/gif';
  if (
    bytes.subarray(0, 4).toString() === 'RIFF' &&
    bytes.subarray(8, 12).toString() === 'WEBP'
  )
    return 'image/webp';
  throw new Error('Unsupported profile image data');
};

export const describeProfileImage = (bytes: Buffer): Media => {
  if (!bytes.length || bytes.length > PROFILE_IMAGE_BYTES)
    throw new Error('Profile image exceeds the media budget');
  return {
    hash: createHash('sha256').update(bytes).digest('hex'),
    bytes: bytes.length,
    mimeType: imageType(bytes),
    representation: 'image',
  };
};

export class ProfileMedia {
  constructor(private readonly directory: string) {}

  async put(bytes: Buffer): Promise<Media> {
    const media = describeProfileImage(bytes);
    const location = this.location(media);
    await fs.mkdir(path.dirname(location), { recursive: true, mode: 0o700 });
    const staging = `${location}.${randomUUID()}.partial`;
    try {
      await fs.writeFile(staging, bytes, { mode: 0o600, flag: 'wx' });
      await fs.rename(staging, location);
    } finally {
      await fs.rm(staging, { force: true });
    }
    return media;
  }

  async resolve(input: Media): Promise<string> {
    await this.read(input);
    return this.location(input);
  }

  async read(input: Media): Promise<Buffer> {
    const media = ProfileMediaSchema.parse(input);
    const location = this.location(media);
    const stat = await fs.lstat(location);
    if (
      !stat.isFile() ||
      stat.size !== media.bytes ||
      stat.size > PROFILE_IMAGE_BYTES
    )
      throw new Error('Profile media integrity check failed');
    const bytes = await fs.readFile(location);
    if (createHash('sha256').update(bytes).digest('hex') !== media.hash)
      throw new Error('Profile media integrity check failed');
    return bytes;
  }

  private location(media: Media): string {
    return path.join(
      this.directory,
      'media',
      media.hash.slice(0, 2),
      `${media.hash}${extensions[media.mimeType]}`,
    );
  }
}
